-- BetterAuth 1.7 schema: account identity scoped by issuer, OAuth protected
-- resources (RFC 8707) with grant-bound resource indicators, DPoP/back-channel
-- logout columns, refresh-token rotation replay window, two-factor lockout.
-- Generated by drizzle-kit; the issuer / application_type backfills are by hand
-- (see https://better-auth.com/docs/guides/1-7-upgrade-guide).
CREATE TABLE "oauth_client_assertions" (
	"id" text PRIMARY KEY NOT NULL,
	"expires_at" timestamp with time zone NOT NULL
);
--> statement-breakpoint
CREATE TABLE "oauth_client_resources" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"client_id" text NOT NULL,
	"resource_id" text NOT NULL,
	"metadata" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "oauth_resources" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"identifier" text NOT NULL,
	"name" text NOT NULL,
	"access_token_ttl" integer,
	"refresh_token_ttl" integer,
	"signing_algorithm" text,
	"signing_key_id" text,
	"allowed_scopes" text[],
	"custom_claims" jsonb,
	"dpop_bound_access_tokens_required" boolean DEFAULT false,
	"disabled" boolean DEFAULT false,
	"policy_version" integer DEFAULT 1,
	"metadata" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "oauth_resources_identifier_unique" UNIQUE("identifier")
);
--> statement-breakpoint
ALTER TABLE "oauth_clients" ALTER COLUMN "metadata" SET DATA TYPE jsonb USING nullif("metadata", '')::jsonb;--> statement-breakpoint
-- Account identity backfill: credential accounts already store the user id as
-- account_id; Google rows get the OIDC issuer; anything else the synthetic
-- local:oauth:<providerId> namespace.
ALTER TABLE "auth_accounts" ADD COLUMN "issuer" text;--> statement-breakpoint
UPDATE "auth_accounts" SET "issuer" = CASE "provider_id"
	WHEN 'credential' THEN 'local:credential'
	WHEN 'google' THEN 'https://accounts.google.com'
	ELSE 'local:oauth:' || "provider_id"
END;--> statement-breakpoint
