-- `type` (web | native | user-agent-based) becomes RFC 7591 application_type;
-- public-ness is now derived from token_endpoint_auth_method = 'none'.
UPDATE "oauth_clients" SET "application_type" = CASE "type"
	WHEN 'web' THEN 'web'
	WHEN 'native' THEN 'native'
	ELSE NULL
END;--> statement-breakpoint
UPDATE "oauth_clients" SET "token_endpoint_auth_method" = 'none'
	WHERE "public" = true AND "token_endpoint_auth_method" IS NULL;--> statement-breakpoint
